from collections import OrderedDict


class LRUCache:
    """A fixed-capacity cache that evicts the least recently used key.

    ``get`` and ``put`` both count as a use of the key involved. When an
    insert would exceed ``capacity``, the least recently used key is
    evicted first. ``capacity`` must be at least 1.
    """

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        """Return the value for *key*, or None if absent; counts as a use."""
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Insert or update *key*; counts as a use and may evict."""
        if key in self._data:
            self._data.move_to_end(key)
            self._data[key] = value
            return
        if len(self._data) >= self.capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self):
        return len(self._data)
